edits.before:
try {
  super.initialize();

  this._handleFocus();
  this._handleClick();
  this._handleHover();
  this._handleKeydown();
  this._handleKeyup();
} catch (error) {
  console.error(error);
}

edits.after:
try {
  super.initialize();

  // Close dropdown when focus leaves the menu
  this.dom.menu.addEventListener('focusout', (event) => {
    const relatedTarget = event.relatedTarget;
    if (relatedTarget && !this.dom.menu.contains(relatedTarget)) {
      if (this.elements.controller && this.elements.controller.isOpen) {
        this.elements.controller.close();
      }
    }
  });

  this._handleFocus();
  this._handleClick();
  this._handleHover();
  this._handleKeydown();
  this._handleKeyup();
} catch (error) {
  console.error(error);
}
